/*
 * A338742  When a(n) is even, a(n) is the number of even digits present so
 *          far in the sequence, a(n) included.
 * https://oeis.org/A338742
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   a(n) is generated by appending all odd natural numbers in *
 *            order and inserting an even number x precisely when the
 *            cumulative * count of even decimal digits seen so far (after
 *            including x) * equals x. This produces the OEIS sequence A338742
 * Range:     u8 n <= 79, u16 n <= 79, u32 n <= 79, u64 n <= 79, u128 n <= 79,
 *            big any n
 * Validated: partial, pass, 79 terms through n = 79 (2026-11-01)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

static seq_t count_even_digits(seq_t x)
{
    seq_t cnt = 0;
    while (x != 0) {
        seq_t digit = x % 10;
        if ((digit & 1) == 0)
            cnt++;
        x /= 10;
    }
    return cnt;
}

seq_t a(idx_t n)
{
    seq_t E = 0;          /* cumulative count of even digits */
    seq_t next_odd = 1;   /* next odd natural number to consider */
    seq_t next_even = 2;  /* next even natural number to consider */
    seq_t result = 0;     /* value at current index */
    idx_t i = 0;

    while (i < n) {
        seq_t e_even = count_even_digits(next_even);

        if (E + e_even == next_even) {
            /* next even satisfies the condition */
            result = next_even;
            E += e_even;
            next_even += 2;
        } else {
            /* append next odd number */
            result = next_odd;
            E += count_even_digits(next_odd);
            next_odd += 2;
        }

        ++i;
    }

    return result;
}
